import bisect
import calendar
import datetime
import re

_NUM = re.compile(r"^[0-9]+$")

# (name, low, high) for the five fields
_FIELDS = (
    ("minute", 0, 59),
    ("hour", 0, 23),
    ("day of month", 1, 31),
    ("month", 1, 12),
    ("day of week", 0, 7),
)


def _parse_number(text, lo, hi, name):
    if not _NUM.match(text):
        raise ValueError(f"invalid number {text!r} in {name} field")
    value = int(text)
    if value < lo or value > hi:
        raise ValueError(f"value {value} out of range {lo}-{hi} in {name} field")
    return value


def _parse_range(text, lo, hi, name):
    a_txt, sep, b_txt = text.partition("-")
    if not sep:
        raise ValueError(f"invalid range {text!r} in {name} field")
    a = _parse_number(a_txt, lo, hi, name)
    b = _parse_number(b_txt, lo, hi, name)
    if a > b:
        raise ValueError(f"range {text!r} has start greater than end in {name} field")
    return a, b


def _parse_field(field, lo, hi, name):
    """Return the set of allowed integer values for one cron field."""
    values = set()
    for item in field.split(","):
        if item == "":
            raise ValueError(f"empty item in {name} field")
        step = 1
        if "/" in item:
            base, _, step_txt = item.partition("/")
            if not _NUM.match(step_txt):
                raise ValueError(f"invalid step {step_txt!r} in {name} field")
            step = int(step_txt)
            if step < 1:
                raise ValueError(f"step must be at least 1 in {name} field")
            if base == "*":
                a, b = lo, hi
            elif "-" in base:
                a, b = _parse_range(base, lo, hi, name)
            else:
                raise ValueError(f"invalid item {item!r} in {name} field")
        else:
            if item == "*":
                a, b = lo, hi
            elif "-" in item:
                a, b = _parse_range(item, lo, hi, name)
            else:
                a = b = _parse_number(item, lo, hi, name)
        values.update(range(a, b + 1, step))
    return values


def _parse(expr):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}")

    parsed = []
    for text, (name, lo, hi) in zip(fields, _FIELDS):
        parsed.append(_parse_field(text, lo, hi, name))
    minutes, hours, doms, months, dows = parsed

    # 7 and 0 are both Sunday.
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    # An expression can never fire only when the day-of-month field alone
    # decides the day and none of its days exist in any allowed month.
    if not dom_star and dow_star:
        possible = False
        for m in months:
            max_len = 29 if m == 2 else calendar.monthrange(2001, m)[1]
            if any(d <= max_len for d in doms):
                possible = True
                break
        if not possible:
            raise ValueError("expression can never fire")

    return (
        sorted(minutes),
        sorted(hours),
        doms,
        sorted(months),
        dows,
        dom_star,
        dow_star,
    )


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    minutes, hours, doms, months, dows, dom_star, dow_star = _parse(expr)
    month_set = set(months)

    def day_matches(y, mo, d):
        dom_ok = d in doms
        if dom_star and dow_star:
            return True
        if dow_star:
            return dom_ok
        dow_ok = (datetime.date(y, mo, d).weekday() + 1) % 7 in dows
        if dom_star:
            return dow_ok
        return dom_ok or dow_ok

    def first_time_on_or_after(h0, m0):
        """Earliest (hour, minute) >= (h0, m0), or None if none left today."""
        i = bisect.bisect_left(hours, h0)
        if i < len(hours) and hours[i] == h0:
            j = bisect.bisect_left(minutes, m0)
            if j < len(minutes):
                return h0, minutes[j]
            i += 1
        if i < len(hours):
            return hours[i], minutes[0]
        return None

    # Earliest possible candidate: next whole minute strictly after `after`.
    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    y, mo = start.year, start.month
    while y <= 3000:
        if mo in month_set:
            days_in_month = calendar.monthrange(y, mo)[1]
            if y == start.year and mo == start.month:
                d0 = start.day
            else:
                d0 = 1
            for d in range(d0, days_in_month + 1):
                if not day_matches(y, mo, d):
                    continue
                if y == start.year and mo == start.month and d == start.day:
                    hm = first_time_on_or_after(start.hour, start.minute)
                    if hm is None:
                        continue
                else:
                    hm = hours[0], minutes[0]
                return datetime.datetime(y, mo, d, hm[0], hm[1])
            # No matching day left in this month; jump to next allowed month.
        # Advance to the next allowed month.
        i = bisect.bisect_right(months, mo)
        if i < len(months):
            mo = months[i]
        else:
            mo = months[0]
            y += 1

    raise ValueError("expression does not fire before the year 3000")
